import{_ as r,a0 as i,w as l,s as a,ao as u,I as e,x as n,a1 as p,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"命令列星期二 ——  序 | LCTT x X-CMD","titleTemplate":false,"description":"命令列星期二 ——  序 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列星期二 ——  序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列星期二 ——  序 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140529 Command Line Tuesdays--The Introductory","title":"命令列星期二 ——  序","tag":"201406","desc":""},"relativePath":"201406/20140529 Command Line Tuesdays--The Introductory.md","filePath":"[post].md"}'),d={name:"201406/20140529 Command Line Tuesdays--The Introductory.md"};function m(T,t,x,L,f,g){const o=i("Link");return l(),a("div",null,[t[16]||(t[16]=u('<h1 id="命令列星期二-——-序" tabindex="-1">命令列星期二 —— 序 <a class="header-anchor" href="#命令列星期二-——-序" aria-label="Permalink to “命令列星期二 ——  序”">​</a></h1><p><strong>嗨，極客們！</strong></p><p>今天，我們介紹給大家一個新的系列節目，它叫命令列星期二。為什麼叫命令列星期二？因為在該系列節目中，每天坐在計算機前的你們，將會試着走出圖形用户界面（GUI）文化的藩籬，從今天開始“讓事情變得簡單而大眾化”。</p><p>當然，如果你訪問過任何與GNU/Linux相關的社區論壇的話，你可能已經看到了，關於GUI和命令列哪個更好的討論非常熱烈。是讓GUI掌控一切，還是隻是學習並享受命令列界（CLI）面帶來的樂趣呢？</p><p><img src="http://sholva.org/assets/images/blog/2009/review-opensuse-11.2/opensuse-terminal.png" alt="Terminal"></p><p>對於使用或拋棄GUI工具的爭論有很多。正方最常提到的優點之一，就是我們是在點擊的計算模式下長大的，所以它基本上就是我們和機器進行交互的一種語言，或者你可以説是一種文化。我們日復一日重複着這樣的模式，點擊那個大按鈕來讓它幹我們需要它乾的事。</p><p>而對於反方，我讀到的關於命令列的優點的最有趣的評論之一，就是你可以通過命令列來更快，更簡單地做更多事情，比GUI工具來得快。但你需要明白的是：你需要學習命令。是的，學習它們，就像學一首詩一樣。</p><p>現在，因為對於我們，半知半解毫無頭緒的用户們，它讓人聽起來就像是某個沒用的雜記小丑表演得表演過頭，太過火了。讓我來用個寓言講得通俗一點吧：</p><h3 id="寓言" tabindex="-1">寓言 <a class="header-anchor" href="#寓言" aria-label="Permalink to “寓言”">​</a></h3><p>我已經用了Linux超過3年了。27歲，是個文學專業學生，我對任何形式的技術都沒有太大的興趣。我直到中學才有了一台屬於自己的計算機，我想大概是17歲那年吧。對於我而言，只用了10年的計算機。我只用過三個程序，BS播放器，Winamp和足球經理，偶爾也用用MS Word。大約三年多以前，我做臨時工時的一位同事，在我正和另外一位同僚談話時告訴我説，有個新版的東西，它一下子就抓住了我的心，它看起來確實與眾不同。我現在想想，它就是Ubuntu的“敏捷的獨角鯨”。在和這位同事討論這個新版本後，他指出了一些常見的優點，這些優點也是我們經常向新手宣傳的，不需要殺毒軟件，啓動快捷，安全性更高，附帶有軟件中心等等之類。最突出的一點：它背後的自由和開源（FOSS）哲學。他用他温和而優雅的方式把我帶了進去。</p><p>我決定來一次嘗試，而從那以後便一發不可收拾。而至於我是怎麼又從第一次對Ubuntu的淺嘗輒止轉而投向openSUSE 11.4的，咋們下回再講吧。而我發現它只是一個完美而甜蜜的小插曲時，那就完完全全另外一回事了。問題在於，我最終進入了Linux領域。這很有趣，感覺很不一樣，它讓我的計算機跑得更好，它也更穩定，我也和它相處得很好（似乎我是在不經意間買到了相當普通的硬件）。似乎Linux並不是一個完全的桌面系統，所以我有時不得不使用終端。但是這麼説吧，它是Linux中一個最為討厭的，最為可怕，最令人不爽的工具之一。如果某些操作沒有GUI可以做的話，我馬上會誠惶誠恐，十分不安了。因為當我從論壇複製/粘貼命令的時候，我都不知道我究竟在幹些什麼。</p><p>隨着時間流逝，情況發生了變化。相對於其他以消費者為導向的系統，發生在我身上的事可能有點與一般人相反。在那三年中，我感覺不是我在玩系統，而是系統在玩我。我學會了怎樣尋找基本問題，提交bug報告，怎樣正確地在論壇上提問。對於碰到的每個問題，我學會了為那些更有能力幫我解決問題的人提供更有用的信息。</p><p>不久以前，我女朋友發泄説，她簡直不敢相信，我主要為了用計算機而用計算機，而不是用它來做一些別的事情。“你只用它來進行音樂收藏和做些Linux的亂七八糟的事情，Nenad. Gaawd”它讓我想啊，使勁想。Linux，特別是openSUSE發行版它成了我的愛好之一。我不是一個專家，不管怎麼看都是這樣，Linux不在我的專業知識範疇內。但我有足夠的知識來搞定它，搞定一些小問題，修改一些配置文件等等。但是我終於認識到，隨着玩Linux日久，對系統的調整日多，我真的需要熟悉一下命令列（CLI）了。我也瞭解到，我在對底層的東西一無所知的情況下對系統胡作非為。我要對着etc大喊大叫了，它究竟是個什麼東西？bin又是個什麼東西？為什麼會有個.sh在後面？問什麼這個文件在這裏？那個文件又在那裏？為什麼我得點擊那一大堆的文件夾來找到正確的文件進行修改？然後，我讀到“你可以用一個命令來簡單地列出某個地方的所有文件”時，它又變得很有趣了，我突然感到迫不及待要想試試了。</p><h3 id="好吧-讓我們幹吧" tabindex="-1">好吧，讓我們幹吧！ <a class="header-anchor" href="#好吧-讓我們幹吧" aria-label="Permalink to “好吧，讓我們幹吧！”">​</a></h3><p>我們來了……。作為一位新的openSUSE的新聞發佈者，我會試着以我所見最有成效的方式來發表我的看法，這樣的方式我想對社區中絕大多數人會奏效。該高舉旗幟，一起開始學習命令列了。如果是哲學理念吸引你到Linux和openSUSE中來的，就像我一樣，那麼是時候走得更遠一點了。</p><p><img src="http://beerepiphany.files.wordpress.com/2010/04/pinky_brain.jpg" alt=""></p><p>看，我就知道在那外頭有一大堆像我這樣的人。我知道，你也許沒有抓住90後極客們的要點，黑屏-綠字-手指在鍵盤上亂飛-讓一切都激情澎湃。但這在很多地方都很有用。我們將以一種有趣的，而又通用的方式來學習，目錄是用來幹什麼，什麼文件放在什麼地方，以及一些最常用的終端命令。在我們在控制台處理一些任務時，這將讓我們更輕鬆一些；在碰到一些問題時，獲得更大的回報。它也會讓bug處理者更輕鬆些，如果他們從我們這頭收到正確的信息的話。它也讓我們的愛好變得樂趣無窮。</p><p>我是説，我的天啊，你已經過渡到連Dilber和xkcd都感到有趣的階段了。是時候到終端下去了。</p><p>附錄：</p><p>要用到的一些參考資料：威廉·肖茨—— 《Linux命令列》,以及克羅地亞黑客韋利米爾·巴克沙，別名魯塞拉斯，《關於最常用命令的簡短教程》。對於你們的要求:</p>',20)),e("ul",null,[t[3]||(t[3]=e("li",null,"每週1到2小時的空閒時間",-1)),t[4]||(t[4]=e("li",null,"一品脱冰凍啤酒或者其它飲料",-1)),e("li",null,[t[1]||(t[1]=n("有人已經指出，使用",-1)),p(o,{href:"http://software.opensuse.org/package/gedit"},{default:s(()=>[...t[0]||(t[0]=[n("Gedit",-1)])]),_:1}),t[2]||(t[2]=n("，或者手工記錄本（你懂的，筆和紙，呵呵）可以讓學習更簡單一些。",-1))])]),t[17]||(t[17]=e("p",null,"肖茨寫的書可是精品，但讀它可要花點時間和毅力。這裏，我盡力讓課程變得更通俗易懂一點，花點時間來幫助你們，而最重要的是——我希望我們能一起學習，一起互相幫助（評論還有論壇，人！！），並且加入一個組織嚴密的openSUSE社區！下週的這個時間（已經會是六月了吧），我們講學習我們的第一部分命令。切記……",-1)),t[18]||(t[18]=e("p",null,[e("strong",null,"盡情享受吧！")],-1)),t[19]||(t[19]=e("hr",null,null,-1)),e("p",null,[t[6]||(t[6]=n("via: ",-1)),p(o,{href:"https://news.opensuse.org/2014/05/27/command-line-tuesdays-the-introductory/"},{default:s(()=>[...t[5]||(t[5]=[n("https://news.opensuse.org/2014/05/27/command-line-tuesdays-the-introductory/",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=n("譯者：",-1)),p(o,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[7]||(t[7]=[n("GOLinux",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=n("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原創翻譯，",-1)),p(o,{href:"http://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[n("Linux中國",-1)])]),_:1}),t[15]||(t[15]=n(" 榮譽推出",-1))])])}const y=r(d,[["render",m]]);export{b as __pageData,y as default};
